{"op":"add","path":"/root","value":"composer"}
{"op":"add","path":"/elements/composer","value":{"type":"Composer","props":{"headline":"Plan your trip, day by day","lede":"Tell us where, when and with whom. We'll fit the days to your budget.","runLabel":"Plan my trip","columns":"2"},"children":["left-col","right-col","run-hint"],"on":{"press":[{"action":"validateForm"},{"action":"run"}]}}}
{"op":"add","path":"/elements/left-col","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"children":["where-when","whos-going"]}}
{"op":"add","path":"/elements/where-when","value":{"type":"FieldGroup","props":{"title":"Where and when"},"children":["trip-name","city-country","dates","must-see"]}}
{"op":"add","path":"/elements/trip-name","value":{"type":"Input","props":{"label":"Trip name","name":"title","placeholder":"Lisbon long weekend","value":{"$bindState":"/inputs/request/title"},"checks":[{"type":"required","message":"Give the trip a name"}]},"children":[]}}
{"op":"add","path":"/elements/city-country","value":{"type":"Grid","props":{"columns":2,"gap":"md"},"children":["city","country"]}}
{"op":"add","path":"/elements/city","value":{"type":"Input","props":{"label":"City","name":"city","value":{"$bindState":"/inputs/request/stay/city"},"checks":[{"type":"required","message":"Which city?"}]},"children":[]}}
{"op":"add","path":"/elements/country","value":{"type":"Select","props":{"label":"Country","name":"country","options":["France","Italy","Japan","Portugal","Spain","United States"],"value":{"$bindState":"/inputs/request/stay/country"},"checks":[{"type":"required","message":"Pick a country"}]},"children":[]}}
{"op":"add","path":"/elements/dates","value":{"type":"DateRange","props":{"label":"Arriving and leaving","from":{"$bindState":"/inputs/request/stay/arriving_on"},"to":{"$bindState":"/inputs/request/stay/leaving_on"}},"children":[]}}
{"op":"add","path":"/elements/must-see","value":{"type":"Chips","props":{"label":"Must-sees","placeholder":"Add a place and press Enter","value":{"$bindState":"/inputs/request/stay/must_see"}},"children":[]}}
{"op":"add","path":"/elements/whos-going","value":{"type":"FieldGroup","props":{"title":"Who's going"},"children":["travellers","with-children","accessibility"]}}
{"op":"add","path":"/elements/travellers","value":{"type":"CompactList","props":{"label":"Travellers","items":{"$bindState":"/inputs/request/travellers"},"primary":"name","secondary":["age","dietary"],"addLabel":"Add a traveller"},"children":[]}}
{"op":"add","path":"/elements/with-children","value":{"type":"Switch","props":{"label":"Kids are coming","name":"with_children","checked":{"$bindState":"/inputs/request/with_children"}},"children":[]}}
{"op":"add","path":"/elements/accessibility","value":{"type":"Input","props":{"label":"Accessibility needs","name":"accessibility","placeholder":"e.g. step-free routes","value":{"$bindState":"/inputs/request/accessibility"}},"children":[]}}
{"op":"add","path":"/elements/right-col","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"children":["budget-group","feel-group"]}}
{"op":"add","path":"/elements/budget-group","value":{"type":"FieldGroup","props":{"title":"Budget"},"children":["budget-row"]}}
{"op":"add","path":"/elements/budget-row","value":{"type":"Grid","props":{"columns":2,"gap":"md"},"children":["budget","currency"]}}
{"op":"add","path":"/elements/budget","value":{"type":"NumberInput","props":{"label":"Total budget","name":"budget","value":{"$bindState":"/inputs/request/budget"}},"children":[]}}
{"op":"add","path":"/elements/currency","value":{"type":"Segmented","props":{"label":"Currency","name":"currency","options":["EUR","USD","GBP","JPY"],"value":{"$bindState":"/inputs/request/currency"}},"children":[]}}
{"op":"add","path":"/elements/feel-group","value":{"type":"FieldGroup","props":{"title":"The feel"},"children":["pace","style","notes","inspiration"]}}
{"op":"add","path":"/elements/pace","value":{"type":"Segmented","props":{"label":"Pace","name":"pace","options":["slow","balanced","packed"],"value":{"$bindState":"/inputs/request/pace"}},"children":[]}}
{"op":"add","path":"/elements/style","value":{"type":"Segmented","props":{"label":"Mostly about","name":"style","options":["culture","food","nature","nightlife","family"],"value":{"$bindState":"/inputs/request/style"}},"children":[]}}
{"op":"add","path":"/elements/notes","value":{"type":"Textarea","props":{"label":"Anything else","name":"notes","placeholder":"A rooftop dinner on the last night…","rows":3,"value":{"$bindState":"/inputs/request/notes"}},"children":[]}}
{"op":"add","path":"/elements/inspiration","value":{"type":"MthdsField","props":{"path":"/inputs/inspiration"},"children":[]}}
{"op":"add","path":"/elements/run-hint","value":{"type":"Text","props":{"text":"Add the trip details to start. The photo is optional.","variant":"muted"},"children":[]}}
